package cli

import (
	"encoding/json"
	"reflect"
	"strings"
	"testing"

	"github.com/ictechgy/gartograph/internal/testutil"
)

// generatedDeadFixture는 생성 파일 하나와 손으로 쓴 파일 하나에 미사용 함수를 하나씩 둔다.
// cgo 산출물(_Cgo_*)과 같은 표지(`// Code generated ... DO NOT EDIT.`)를 C 컴파일러 없이 재현한다.
func generatedDeadFixture(t *testing.T) string {
	t.Helper()
	return testutil.WriteModule(t, map[string]string{
		"main.go": "package main\n\nfunc main() {}\n\nfunc handwrittenUnused() {}\n",
		"zz_generated.go": "// Code generated by fixturegen; DO NOT EDIT.\n\npackage main\n\n" +
			"func generatedUnused() {}\n",
	})
}

// dead 보고는 생성 파일 출신 보고에 generated 사실을 싣고, 그런 보고가 있을 때만 그 수를
// limitation으로 센다. 기본 보고 범위는 그대로다 — 생성 심볼도 보고되고 --strict에 남는다.
func TestFeedbackDeadMarksGeneratedFindings(t *testing.T) {
	dir := generatedDeadFixture(t)
	var rep struct {
		Unreachable []struct {
			ID        string `json:"id"`
			Generated bool   `json:"generated"`
		} `json:"unreachable"`
		Limitations []string `json:"limitations"`
	}
	if err := json.Unmarshal([]byte(cliReport(t, "dead", "--format", "json", "--dir", dir)), &rep); err != nil {
		t.Fatal(err)
	}
	got := map[string]bool{}
	for _, f := range rep.Unreachable {
		got[f.ID] = f.Generated
	}
	if generated, ok := got["example.com/fixture.generatedUnused"]; !ok || !generated {
		t.Fatalf("generated finding must stay reported and carry generated: true: %+v", rep.Unreachable)
	}
	if generated, ok := got["example.com/fixture.handwrittenUnused"]; !ok || generated {
		t.Fatalf("hand-written finding must not be marked generated: %+v", rep.Unreachable)
	}
	if !hasLimitation(rep.Limitations, "1 unreachable findings", "generated files") {
		t.Fatalf("generated findings must be counted in a limitation: %v", rep.Limitations)
	}
	code, text, errb := run(t, "dead", "--dir", dir, "--strict")
	if code != 1 {
		t.Fatalf("generated findings must still fail --strict: %d %s", code, errb)
	}
	if !strings.Contains(text, "unreachable func: example.com/fixture.generatedUnused (generated)\n") ||
		strings.Contains(text, "handwrittenUnused (generated)") {
		t.Fatalf("text report must mark only the generated finding:\n%s", text)
	}
	// 생성 보고가 없으면 조용하다 — limitation은 실제로 센 수만 말한다.
	var rooted struct {
		Limitations []string `json:"limitations"`
	}
	out := cliReport(t, "dead", "--format", "json", "--dir", dir, "--root", "example.com/fixture.generatedUnused")
	if err := json.Unmarshal([]byte(out), &rooted); err != nil {
		t.Fatal(err)
	}
	if hasLimitation(rooted.Limitations, "", "generated files") {
		t.Fatalf("no generated finding, no limitation: %v", rooted.Limitations)
	}
}

// 태그가 붙은 필드도 지금처럼 보고되고 --strict에 남는다. 보고는 키를 싣고, 그런 필드 보고가 있을 때만 그 수를
// limitation으로 센다 — 인코더·ORM이 reflection으로 읽는다는 사실을 보고에서 바로 볼 수 있어야
// 에이전트가 와이어 형식을 깨는 삭제를 하지 않는다.
func TestFeedbackDeadReportsTaggedFieldsWithKeys(t *testing.T) {
	dir := testutil.WriteModule(t, map[string]string{
		"main.go": "package main\n\nfunc main() { _ = R{} }\n\n" +
			"type R struct {\n\tA int `json:\"a\"`\n\tB int `json:\"-\"`\n\tc int\n\tD int `yaml:\"d\" db:\"d\"`\n}\n",
	})
	var rep struct {
		Unreachable []struct {
			ID      string   `json:"id"`
			TagKeys []string `json:"tagKeys"`
		} `json:"unreachable"`
		Limitations []string `json:"limitations"`
	}
	if err := json.Unmarshal([]byte(cliReport(t, "dead", "--format", "json", "--dir", dir)), &rep); err != nil {
		t.Fatal(err)
	}
	got := map[string][]string{}
	for _, f := range rep.Unreachable {
		got[f.ID] = f.TagKeys
	}
	want := map[string][]string{
		"example.com/fixture.(R).A": {"json"}, "example.com/fixture.(R).B": nil,
		"example.com/fixture.(R).c": nil, "example.com/fixture.(R).D": {"db", "yaml"},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("tagged fields must stay reported with their keys: got %v, want %v", got, want)
	}
	if !hasLimitation(rep.Limitations, "2 unreachable fields carry struct tags", "reflection") {
		t.Fatalf("tagged field findings must be counted in a limitation: %v", rep.Limitations)
	}
	if code, _, errb := run(t, "dead", "--dir", dir, "--strict"); code != 1 {
		t.Fatalf("tagged fields must still fail --strict: %d %s", code, errb)
	}
	var plain struct {
		Limitations []string `json:"limitations"`
	}
	untagged := testutil.WriteModule(t, map[string]string{
		"main.go": "package main\n\nfunc main() { _ = R{} }\n\ntype R struct{ c int }\n",
	})
	if err := json.Unmarshal([]byte(cliReport(t, "dead", "--format", "json", "--dir", untagged)), &plain); err != nil {
		t.Fatal(err)
	}
	if hasLimitation(plain.Limitations, "", "struct tags") {
		t.Fatalf("no tagged finding, no limitation: %v", plain.Limitations)
	}
}

// 테스트에서만 import되는 헬퍼 패키지는 기본 실행에서 orphan·unreachable로 남되(보고 범위는 그대로), metrics와
// dead 보고가 그 몫이 테스트를 수확하지 않은 결과라는 limitation을 싣는다. --tests로 수확하면 헬퍼가 살아나고
// limitation도 없다.
func TestFeedbackTestOnlyHelperIsExplained(t *testing.T) {
	dir := testutil.WriteModule(t, map[string]string{
		"main.go":                   "package main\n\nimport \"example.com/fixture/lib\"\n\nfunc main() { lib.Run() }\n",
		"lib/lib.go":                "package lib\n\nfunc Run() {}\n",
		"lib/lib_test.go":           "package lib\n\nimport (\n\t\"testing\"\n\n\t\"example.com/fixture/internal/helper\"\n)\n\nfunc TestRun(t *testing.T) { helper.Help() }\n",
		"internal/helper/helper.go": "package helper\n\nfunc Help() {}\n",
		".gartograph.yml":           "components:\n  app: [\".\", \"lib\"]\n  helper: [\"internal/helper\"]\ndeps:\n  app: []\n",
	})
	const note = "1 packages are imported only by _test.go files of other packages (first: example.com/fixture/internal/helper)"
	var metrics struct {
		Orphans     []string `json:"orphans"`
		Limitations []string `json:"limitations"`
	}
	if err := json.Unmarshal([]byte(cliReport(t, "metrics", "--format", "json", "--dir", dir)), &metrics); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(metrics.Orphans, []string{"example.com/fixture/internal/helper"}) ||
		!hasLimitation(metrics.Limitations, note, "use --tests") {
		t.Fatalf("metrics must keep the orphan and explain it: %+v", metrics)
	}
	var dead struct {
		Unreachable []struct {
			ID string `json:"id"`
		} `json:"unreachable"`
		Limitations []string `json:"limitations"`
	}
	if err := json.Unmarshal([]byte(cliReport(t, "dead", "--format", "json", "--dir", dir)), &dead); err != nil {
		t.Fatal(err)
	}
	if len(dead.Unreachable) != 1 || dead.Unreachable[0].ID != "example.com/fixture/internal/helper.Help" ||
		!hasLimitation(dead.Limitations, note, "use --tests") {
		t.Fatalf("dead must keep the helper finding and explain it: %+v", dead)
	}
	dead.Unreachable, dead.Limitations = nil, nil
	if err := json.Unmarshal([]byte(cliReport(t, "dead", "--format", "json", "--dir", dir, "--tests")), &dead); err != nil {
		t.Fatal(err)
	}
	if len(dead.Unreachable) != 0 || hasLimitation(dead.Limitations, "", "imported only by _test.go files") {
		t.Fatalf("--tests must harvest the importer: %+v", dead)
	}
}
